const products=[{id:'chair',name:'The Sunday Chair',category:'Furniture',note:'An invitation to slow down',price:18900,image:'assets/chair.jpg',label:'THE EVERYDAY FAVORITE',material:'Soft upholstery · Natural oak',description:'A generous seat for a favorite book, an unhurried coffee, and everything in between. The Sunday brings a softer rhythm to your living space.',color:'#9f825f'},{id:'lamp',name:'The Arc Table Light',category:'Lighting',note:'A softer kind of glow',price:6400,image:'assets/lamp.jpg',label:'A BRIGHT IDEA',material:'Powder-coated metal · Warm light',description:'A simple silhouette that makes a quiet statement. A warm pool of light for your desk, your bedside, or your evening wind-down.',color:'#d9d8d0'},{id:'vase',name:'The Studio Vessels',category:'Objects',note:'Beautiful with or without blooms',price:2800,image:'assets/vase.jpg',label:'SMALL OBJECT, BIG FEELING',material:'Ceramic · Chalk finish',description:'Sculptural forms with a beautifully understated finish. A considered accent for shelves, tables, and the spaces that make a home yours.',color:'#e2ded2'}];
const money=n=>'₹'+n.toLocaleString('en-IN');let cart={};let toastTimer;const $=id=>document.getElementById(id);
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function renderProducts(category='All'){const selected=products.filter(p=>category==='All'||p.category===category);$('products').innerHTML=selected.map(p=>`<article><div class="product-media"><button class="product-view" data-view="${p.id}" aria-label="View ${p.name}"><img src="${p.image}" alt="${p.name}" loading="lazy"></button><span class="tag">${p.label}</span><button class="add" data-add="${p.id}" aria-label="Add ${p.name} to bag">+</button></div><div class="product-info"><div><h3>${p.name}</h3><p>${p.note}</p><span class="swatch" style="background:${p.color}" aria-hidden="true"></span></div><span class="price">${money(p.price)}</span></div></article>`).join('');$('result-count').textContent=`${selected.length} considered ${selected.length===1?'piece':'pieces'}`}
function add(id){if(!products.some(p=>p.id===id))throw Error('Unknown product');cart[id]=(cart[id]||0)+1;renderCart();notify('A good choice. Added to your bag.');return {productId:id,quantity:cart[id]}}
function renderCart(){const selected=products.filter(p=>cart[p.id]);$('cart-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);$('cart-items').innerHTML=selected.length?selected.map(p=>`<article class="cart-row"><img src="${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p>${money(p.price)}</p><div class="quantity"><button data-qty="${p.id}" data-change="-1" aria-label="Decrease ${p.name} quantity">−</button><span aria-label="Quantity">${cart[p.id]}</span><button data-qty="${p.id}" data-change="1" aria-label="Increase ${p.name} quantity">+</button><button class="remove" data-remove="${p.id}" aria-label="Remove ${p.name}">Remove</button></div></div></article>`).join(''):'<div class="empty"><h3>Room for something good.</h3><p>Your bag is empty. Find your everyday favorite.</p><button class="button dark" data-close="cart-dialog">Explore the collection ↗</button></div>';
const subtotal=selected.reduce((s,p)=>s+p.price*cart[p.id],0);$('cart-summary').innerHTML=selected.length?`<div class="total"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><small>${subtotal>=10000?'Complimentary delivery included.':'Delivery calculated at checkout.'}</small><button class="button dark" id="checkout">Try demo checkout <span>↗</span></button><small>Concept store. No payment or real order will be placed.</small>`:''}
function showProduct(id){const p=products.find(p=>p.id===id);if(!p)return;$('detail').innerHTML=`<img src="${p.image}" alt="${p.name}"><div><p class="eyebrow">${p.category.toUpperCase()}</p><h2 id="detail-title">${p.name}</h2><p>${p.description}</p><p>${p.material}</p><strong>${money(p.price)}</strong><button class="button dark" data-add="${p.id}">Add to bag <span>+</span></button></div>`;$('product-dialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.category){document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderProducts(b.dataset.category)}if(b.dataset.view)showProduct(b.dataset.view);if(b.dataset.add)add(b.dataset.add);if(b.dataset.close)$(b.dataset.close).close();if(b.id==='open-cart'){renderCart();$('cart-dialog').showModal()}if(b.dataset.qty){cart[b.dataset.qty]+=Number(b.dataset.change);if(cart[b.dataset.qty]<=0)delete cart[b.dataset.qty];renderCart()}if(b.dataset.remove){delete cart[b.dataset.remove];renderCart()}if(b.id==='checkout'){$('cart-items').innerHTML='<div class="empty"><p class="eyebrow">LOOKS GOOD ON YOU</p><h3>Your demo order is complete.</h3><p>Thanks for exploring FORMA. No payment was taken and no real order was placed.</p><button class="button dark" data-close="cart-dialog">Keep exploring ↗</button></div>';$('cart-summary').innerHTML='';cart={};$('cart-count').textContent='0'}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
renderProducts();renderCart();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_products',description:'Read the FORMA concept store product catalog.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>products.map(({id,name,category,price})=>({id,name,category,price,currency:'INR'}))})).catch(()=>{})}catch{}}
